    if (e.key.toLowerCase() !== 'b' || e.repeat || held) return
    if (e.target instanceof HTMLElement && e.target.closest('button')) return
    held = plates.map((p) => p.dataset.state)
    plates.forEach((p) => set(p, 'before'))
  })
  addEventListener('keyup', (e) => {
    if (e.key.toLowerCase() !== 'b' || !held) return
    plates.forEach((p, i) => set(p, held[i]))
    held = null
  })
</script>
`

