import { chromium } from 'playwright'

const LABEL = process.argv[2] ?? '?'
const RUNS = 3
const PAGES = [
  ['product detail', '/products/trailmaster-x4-tent', 1440],
  ['product detail', '/products/trailmaster-x4-tent', 390],
  ['category grid', '/products/category/tents', 390],
  ['category grid', '/products/category/tents', 1440],
]

const median = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]

const browser = await chromium.launch()
console.log(`--- ${LABEL} --- (median of ${RUNS}, throttled 1.6Mbps / 150ms RTT / 4x CPU)`)
for (const [label, url, width] of PAGES) {
  const fcps = []
  const lcps = []
  for (let run = 0; run < RUNS; run += 1) {
    const context = await browser.newContext({ viewport: { width, height: 844 }, deviceScaleFactor: 2 })
    const page = await context.newPage()
    const cdp = await context.newCDPSession(page)
    await cdp.send('Network.emulateNetworkConditions', {
      offline: false,
      downloadThroughput: (1.6 * 1024 * 1024) / 8,
      uploadThroughput: (750 * 1024) / 8,
      latency: 150,
    })
    await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 })
    await page.goto('http://127.0.0.1:3400' + url, { waitUntil: 'load' })
    const t = await page.evaluate(
      () =>
        new Promise((resolve) => {
          let lcp = 0
          new PerformanceObserver((l) => {
            const e = l.getEntries()
            lcp = e[e.length - 1].startTime
          }).observe({ type: 'largest-contentful-paint', buffered: true })
          setTimeout(() => {
            const fcp = performance.getEntriesByName('first-contentful-paint')[0]
            resolve({ fcp: fcp ? Math.round(fcp.startTime) : null, lcp: Math.round(lcp) })
          }, 2500)
        })
    )
    fcps.push(t.fcp)
    lcps.push(t.lcp)
    await context.close()
  }
  console.log(
    `  ${label.padEnd(15)} ${String(width).padEnd(5)} FCP ${String(median(fcps)).padStart(5)}ms   LCP ${String(median(lcps)).padStart(5)}ms`
  )
}
await browser.close()

